  [1328261] = { "La pecora lancia un incantesimo sul giocatore per conferirgli il progresso della missione.", "La Pecora Fuggita ti sta seguendo.", 0x8abb825a, 0x6a41c655, "uu" },
  [1328348] = { "Gettane una manciata nel Fuoco da Campo per trasformarne le fiamme.\n|cFFffffffRichiede WoW: Forever Launch Celebration |r", nil, 0xbd934ce5, nil, "um" },
  [1328370] = { "Riduce il tempo di lancio del tuo incantesimo ⟦Turn Undead=Scaccia i Non Morti⟧ di $D1 e il suo tempo di recupero di $D2, e gli permette di influenzare anche i Demoni.", nil, 0x7753f89c, nil, "um" },
  [1328372] = { "Il nemico Non Morto o Demone bersaglio è costretto a fuggire per un massimo di $D1. I danni subiti possono interrompere l'effetto. Si può scacciare un solo bersaglio alla volta.", "Costretto a fuggire.", 0x6bbfd10d, 0x7a42271d, "uu" },
  [1328373] = { "Il nemico Non Morto o Demone bersaglio è costretto a fuggire per un massimo di $D1. I danni subiti possono interrompere l'effetto. Si può scacciare un solo bersaglio alla volta.", "Costretto a fuggire.", 0x6bbfd10d, 0x7a42271d, "uu" },
  [1328374] = { "Il nemico Non Morto o Demone bersaglio è costretto a fuggire per un massimo di $D1. I danni subiti possono interrompere l'effetto. Si può scacciare un solo bersaglio alla volta.", "Costretto a fuggire.", 0x6bbfd10d, 0x7a42271d, "uu" },
  [1328375] = { "La fiamma incantata risuona dentro di te. Gli effetti dei Fuochi da Campo ottenuti mentre sei sotto questo effetto durano più a lungo.", "La fiamma incantata risuona dentro di te. Gli effetti del fuoco da campo ottenuti mentre sei sotto questo effetto durano più a lungo.", 0x30c0d5eb, 0x30c0d5eb, "uu" },
  [1328544] = { "Riduce di $D1 il tempo di recupero della tua abilità ⟦Holy Strike=Assalto Sacro⟧. Inoltre, ⟦Holy Strike=Assalto Sacro⟧ ora colpisce con lo scudo, attivando i tuoi talenti ⟦Holy Shield=Scudo Benedetto⟧ e Specializzazione: Scudo attivi senza consumarne le cariche né attivarne i tempi di recupero, e ti permette di bloccare gli incantesimi per $D2.", nil, 0x95161ba0, nil, "um" },
  [1328546] = { "Riduce del $N1% la durata degli effetti di stordimento e ammaliamento su di te.", nil, 0xb8ddd0b0, nil, "um" },
  [1328548] = { "Presta un giuramento per proteggere l'alleato bersaglio per $D1, aumentando su di lui le cure della tua ⟦Holy Light=Luce Sacra⟧ fino a $N2, del tuo ⟦Flash of Light=Lampo di Luce⟧ fino a $N3 e della tua ⟦Holy Shock=Folgore Sacra⟧ fino a $N4. Il Paladino può prestare un solo ⟦Oath of Light=Giuramento della Luce⟧ alla volta.", "Riceve cure aumentate fino a $N1 da ⟦Holy Light=Luce Sacra⟧ dell'incantatore, fino a $N2 da ⟦Flash of Light=Lampo di Luce⟧ e fino a $N3 da ⟦Holy Shock=Folgore Sacra⟧.", 0x06c037e4, 0x4d99b40f, "uu" },
  [1328550] = { "Aumenta del $N1% la probabilità di critico della tua ⟦Holy Shock=Folgore Sacra⟧ quando la lanci su alleati non sotto l'effetto del tuo ⟦Oath of Light=Giuramento della Luce⟧.", nil, 0xbbd28c64, nil, "um" },
  [1328551] = { "Può bloccare gli incantesimi per $D1.", "Può bloccare gli incantesimi.", 0xd44bf145, 0x40dfddbb, "uu" },
  [1328569] = { "Ogni volta che curi un bersaglio diverso da te con ⟦Flash Heal=Cura Rapida⟧, vieni curato del $N1% di tale ammontare. Questa cura non genera minaccia.", nil, 0xc19d8b90, nil, "um" },
  [1328613] = { "La tua abilità ⟦Ferocious Bite=Morso Feroce⟧ non converte più l'energia in eccesso in danni, ma infligge comunque danni aggiuntivi in base all'energia in eccesso.", nil, 0x71805175, nil, "um" },
  [1328616] = { "Lacera il bersaglio nemico, facendolo sanguinare per $N1 danni in $D1 più il $N3% dei danni dell'arma per ogni applicazione di Lacerazione già presente sul bersaglio. Genera una grande quantità di minaccia. Questo effetto si cumula fino a $N4 volte sullo stesso bersaglio.", "$N1 danni ogni $D1.", 0x58e2b595, 0x8522e0de, "uu" },
  [1328617] = { "Lacera il bersaglio nemico, facendolo sanguinare per $N1 danni in $D1 più il $N3% dei danni dell'arma per ogni applicazione di Lacerazione già presente sul bersaglio. Genera una grande quantità di minaccia. Questo effetto si cumula fino a $N4 volte sullo stesso bersaglio.", "$N1 danni ogni $D1.", 0x58e2b595, 0x8522e0de, "uu" },
  [1328618] = { "Mossa risolutiva che infligge danni per punto combo e converte ogni punto di energia in più in $N1 danni aggiuntivi. I danni aumentano con la potenza d'attacco.\n $N2 punto: $N3-$N4 danni\n $N5 punti: $N6-$N7 danni\n $N8 punti: $N9-$N10 danni\n $N11 punti: $N12-$N13 danni\n $N14 punti: $N15-$N16 danni", nil, 0x1ff654b9, nil, "um" },
  [1328621] = { "Quando il tuo Rinvigorimento o la tua Ricrescita scade per fine durata, il bersaglio viene curato istantaneamente di un ammontare pari al $N1% del tuo Spirito. Se uno dei due incantesimi scade perché dissolto, il bersaglio viene invece curato del $N2% del tuo Spirito.", nil, 0xb02ad48c, nil, "um" },
  [1328749] = { "Entra in comunione con il ⟦Emerald Dream=Sogno di Smeraldo⟧ per sottomettere Nythus.", "In comunione con il ⟦Emerald Dream=Sogno di Smeraldo⟧ per soggiogare Nythus.", 0xd3f8a4cd, 0x663f60a8, "uu" },
